// ratelimit/ratelimit.go
package ratelimit

import (
	"errors"
	"math"
	"sync"
	"time"
)

// Clock abstracts time so tests can drive it deterministically.
type Clock interface {
	Now() time.Time
}

// RealClock returns the system time.
type RealClock struct{}

func (RealClock) Now() time.Time { return time.Now() }

// Limiter is a concurrency-safe token-bucket rate limiter.
//
// Tokens are refilled continuously at rate tokens per second, up to max.
// AllowN consumes n tokens if and only if n tokens are currently available.
type Limiter struct {
	mu       sync.Mutex
	clock    Clock
	rate     float64 // tokens per second
	max      float64
	tokens   float64
	last     time.Time
	maxBurst float64
}

// New constructs a Limiter.
//
// rate must be > 0 and finite; max must be > 0 and finite.
// burst must be > 0 and finite, and must not exceed max.
// The bucket starts full.
func New(clock Clock, rate, max, burst float64) (*Limiter, error) {
	if clock == nil {
		return nil, errors.New("ratelimit: nil clock")
	}
	if !isPositiveFinite(rate) {
		return nil, errors.New("ratelimit: rate must be > 0 and finite")
	}
	if !isPositiveFinite(max) {
		return nil, errors.New("ratelimit: max must be > 0 and finite")
	}
	if !isPositiveFinite(burst) {
		return nil, errors.New("ratelimit: burst must be > 0 and finite")
	}
	if burst > max {
		return nil, errors.New("ratelimit: burst must not exceed max")
	}
	now := clock.Now()
	return &Limiter{
		clock:    clock,
		rate:     rate,
		max:      max,
		tokens:   burst,
		last:     now,
		maxBurst: burst,
	}, nil
}

// AllowN reports whether n tokens can be consumed now.
//
// It is safe for concurrent use. On success it atomically consumes n tokens.
// n must be > 0 and finite; non-positive or invalid n returns false.
func (l *Limiter) AllowN(n float64) bool {
	if !isPositiveFinite(n) {
		return false
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	now := l.clock.Now()
	l.tokens = l.refillLocked(now)
	if n > l.tokens {
		return false
	}
	l.tokens -= n
	return true
}

// refillLocked advances the bucket from l.last to now and clamps to max.
// The caller must hold l.mu.
func (l *Limiter) refillLocked(now time.Time) float64 {
	elapsed := now.Sub(l.last)
	if elapsed > 0 {
		l.tokens += float64(elapsed) * (l.rate / float64(time.Second))
		if l.tokens > l.max {
			l.tokens = l.max
		}
	}
	l.last = now
	return l.tokens
}

func isPositiveFinite(v float64) bool {
	return !math.IsNaN(v) && !math.IsInf(v, 0) && v > 0
}
