package ratelimit

import (
	"errors"
	"sync"
	"testing"
	"time"
)

type fakeClock struct {
	mu  sync.Mutex
	now time.Time
}

func newFakeClock() *fakeClock {
	return &fakeClock{now: time.Unix(1_700_000_000, 0)}
}

func (f *fakeClock) Now() time.Time {
	f.mu.Lock()
	defer f.mu.Unlock()
	return f.now
}

func (f *fakeClock) Advance(d time.Duration) {
	f.mu.Lock()
	defer f.mu.Unlock()
	f.now = f.now.Add(d)
}

func TestNewTokenBucketValidation(t *testing.T) {
	fc := newFakeClock()
	tests := []struct {
		name     string
		clock    Clock
		capacity float64
		rate     float64
		wantErr  bool
	}{
		{"nil clock", nil, 1, 1, true},
		{"zero capacity", fc, 0, 1, true},
		{"negative capacity", fc, -1, 1, true},
		{"zero rate", fc, 1, 0, true},
		{"negative rate", fc, 1, -1, true},
		{"valid", fc, 5, 2, false},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			_, err := NewTokenBucket(tc.clock, tc.capacity, tc.rate)
			if tc.wantErr && err == nil {
				t.Fatalf("expected error, got nil")
			}
			if !tc.wantErr && err != nil {
				t.Fatalf("unexpected error: %v", err)
			}
		})
	}
}

func TestAllowN(t *testing.T) {
	fc := newFakeClock()
	tb, err := NewTokenBucket(fc, 3, 1) // 3 capacity, 1 token/sec
	if err != nil {
		t.Fatal(err)
	}

	// Drain the bucket.
	if !tb.AllowN(3) {
		t.Fatal("expected to allow 3 tokens")
	}
	if tb.AllowN(1) {
		t.Fatal("expected deny when empty")
	}

	// Advance 1s -> exactly 1 token refilled.
	fc.Advance(time.Second)
	if !tb.AllowN(1) {
		t.Fatal("expected to allow 1 token after 1s")
	}
	if tb.AllowN(1) {
		t.Fatal("expected deny after consuming refilled token")
	}

	// Advance 2s -> capped at capacity.
	fc.Advance(2 * time.Second)
	if !tb.AllowN(3) {
		t.Fatal("expected to allow full capacity after refill")
	}
	if tb.AllowN(1) {
		t.Fatal("expected deny after refill drain")
	}

	// Invalid n.
	if tb.AllowN(0) {
		t.Fatal("expected deny for n=0")
	}
	if tb.AllowN(-1) {
		t.Fatal("expected deny for negative n")
	}
}

func TestAllowNConcurrent(t *testing.T) {
	fc := newFakeClock()
	tb, err := NewTokenBucket(fc, 100, 1000)
	if err != nil {
		t.Fatal(err)
	}
	const workers = 8
	const perWorker = 100
	var wg sync.WaitGroup
	allowed := make(chan int, workers*perWorker)
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			n := 0
			for i := 0; i < perWorker; i++ {
				if tb.AllowN(1) {
					n++
				}
			}
			allowed <- n
		}()
	}
	wg.Wait()
	close(allowed)
	total := 0
	for c := range allowed {
		total += c
	}
	if total != 100 {
		t.Fatalf("expected exactly 100 allowed (capacity), got %d", total)
	}
}

func TestTokensObservability(t *testing.T) {
	fc := newFakeClock()
	tb, err := NewTokenBucket(fc, 10, 2)
	if err != nil {
		t.Fatal(err)
	}
	if got := tb.Tokens(); got != 10 {
		t.Fatalf("expected full bucket, got %v", got)
	}
	if !tb.AllowN(4) {
		t.Fatal("expected allow 4")
	}
	if got := tb.Tokens(); got != 6 {
		t.Fatalf("expected 6 tokens, got %v", got)
	}
	fc.Advance(3 * time.Second) // +6 tokens, capped at 10
	if got := tb.Tokens(); got != 10 {
		t.Fatalf("expected capped 10 tokens, got %v", got)
	}
}

func TestErrorsAreDistinct(t *testing.T) {
	_, err := NewTokenBucket(nil, 1, 1)
	if !errors.Is(err, errors.New("ratelimit: clock must not be nil")) {
		t.Fatalf("unexpected error text: %v", err)
	}
}
